/*
 * Standalone TPC-H supplier join and nation aggregation experiment.
 * Input files contain the raw .tbl rows generated by dbgen.
 */
#include <array>
#include <charconv>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {

constexpr int nations = 25;
using Clock = std::chrono::steady_clock;
using Total = unsigned long long;

struct Fact {
    uint32_t supplier;
    uint32_t line;
};

struct Group {
    Total count;
    Total sum;

    bool operator==(const Group &other) const
    {
        return count == other.count && sum == other.sum;
    }
};

using Groups = std::array<Group, nations>;

double elapsed_ms(Clock::time_point start)
{
    return std::chrono::duration<double, std::milli>(Clock::now() - start).count();
}

std::ifstream open_input(const std::string &path)
{
    std::ifstream input(path);
    if (!input)
        throw std::runtime_error("cannot open " + path);
    return input;
}

size_t next_column(const std::string &row, size_t start)
{
    size_t end = row.find('|', start);
    if (end == std::string::npos)
        throw std::runtime_error("missing column separator in TPC-H row");
    return end + 1;
}

uint32_t integer_column(const std::string &row, size_t start, size_t next)
{
    uint32_t value;
    const char *end = row.data() + next - 1;
    auto parsed = std::from_chars(row.data() + start, end, value);
    if (parsed.ec != std::errc{} || parsed.ptr != end)
        throw std::runtime_error("invalid integer in TPC-H row");
    return value;
}

std::vector<int8_t> load_supplier(const std::string &directory)
{
    std::ifstream input = open_input(directory + "/supplier.tbl");
    std::vector<int8_t> by_supplier(1, -1);
    std::string row;
    while (std::getline(input, row)) {
        size_t name_column = next_column(row, 0);
        size_t address_column = next_column(row, name_column);
        size_t nation_column = next_column(row, address_column);
        uint32_t supplier = integer_column(row, 0, name_column);
        uint32_t nation = integer_column(row, nation_column, next_column(row, nation_column));
        if (supplier == 0 || supplier >= (uint32_t{1} << 26) || nation >= nations)
            throw std::runtime_error("supplier or nation key is outside the prototype's range");
        if (supplier >= by_supplier.size())
            by_supplier.resize(supplier + 1, -1);
        if (by_supplier[supplier] >= 0)
            throw std::runtime_error("duplicate supplier key");
        by_supplier[supplier] = static_cast<int8_t>(nation);
    }
    if (!input.eof())
        throw std::runtime_error("failed while reading supplier.tbl");
    return by_supplier;
}

std::vector<Fact> load_lineitem(const std::string &directory)
{
    std::ifstream input = open_input(directory + "/lineitem.tbl");
    std::vector<Fact> facts;
    std::string row;
    while (std::getline(input, row)) {
        size_t part_column = next_column(row, 0);
        size_t supplier_column = next_column(row, part_column);
        size_t line_column = next_column(row, supplier_column);
        uint32_t supplier = integer_column(row, supplier_column, line_column);
        uint32_t line = integer_column(row, line_column, next_column(row, line_column));
        if (line < 1 || line > 7)
            throw std::runtime_error("line numbers must be in the TPC-H range 1..7");
        facts.push_back(Fact{supplier, line});
    }
    if (!input.eof())
        throw std::runtime_error("failed while reading lineitem.tbl");
    return facts;
}

Groups aggregate_cpu(const std::vector<int8_t> &by_supplier, const std::vector<Fact> &facts)
{
    Groups groups{};
    for (const Fact &fact : facts) {
        if (fact.supplier < by_supplier.size()) {
            int nation = by_supplier[fact.supplier];
            if (nation >= 0) {
                groups[nation].count++;
                groups[nation].sum += fact.line;
            }
        }
    }
    return groups;
}

void print_groups(const Groups &groups)
{
    /* Match psql -qAt output for the native GROUP BY ordered by nation key. */
    for (int nation = 0; nation < nations; nation++) {
        if (groups[nation].count)
            std::printf("%d|%llu|%llu\n", nation, groups[nation].count, groups[nation].sum);
    }
}

} // namespace

int main(int argc, char **argv)
{
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s TPC_H_DATA_DIRECTORY\n", argv[0]);
        return 2;
    }
    try {
        auto start = Clock::now();
        auto by_supplier = load_supplier(argv[1]);
        double supplier_ms = elapsed_ms(start);

        start = Clock::now();
        auto facts = load_lineitem(argv[1]);
        double lineitem_ms = elapsed_ms(start);

        start = Clock::now();
        auto groups = aggregate_cpu(by_supplier, facts);
        double cpu_ms = elapsed_ms(start);

        print_groups(groups);
        std::fprintf(stderr, "rows,supplier_parse_ms,lineitem_parse_ms,cpu_ms\n");
        std::fprintf(stderr, "%zu,%.3f,%.3f,%.3f\n", facts.size(), supplier_ms, lineitem_ms, cpu_ms);
        return 0;
    } catch (const std::exception &ex) {
        std::fprintf(stderr, "%s\n", ex.what());
        return 1;
    }
}
